// Translations shared with the desktop app (app/src/locales/*.json, converted by
// tool/gen_strings.py). Keys, i18next-style "{{name}}" interpolation and "_one"/"_few"/"_other"
// plural suffixes work exactly like on desktop. "{{appName}}" is the brand name (lib/brand.g.dart,
// generated by scripts/brand.mjs) unless the caller passes its own value.

import 'dart:ui' as ui;

import 'package:flutter/widgets.dart';

import '../brand.g.dart';
import 'strings.g.dart';

export '../brand.g.dart';

/// Supported languages, in the order shown in Settings → Language.
const List<({String code, String label})> kLanguages = [
  (code: 'en', label: 'English'),
  (code: 'ro', label: 'Română'),
  (code: 'it', label: 'Italiano'),
];

/// Language of the system if supported, otherwise English.
String systemLanguage() {
  for (final l in ui.PlatformDispatcher.instance.locales) {
    final code = l.languageCode.toLowerCase();
    if (kStrings.containsKey(code)) return code;
  }
  return 'en';
}

/// Current language (also used outside of widgets, e.g. for notifications).
String currentLanguage = 'en';

/// CLDR plural category for integers in [lang].
String pluralCategory(String lang, int n) {
  if (lang == 'ro') {
    if (n == 1) return 'one';
    final m = n % 100;
    if (n == 0 || (m >= 1 && m <= 19)) return 'few';
    return 'other';
  }
  return n == 1 ? 'one' : 'other';
}

/// Translates [key] in [lang]. [args] fill "{{name}}" placeholders; [count] selects the plural
/// form and is also available as "{{count}}". "{{appName}}" defaults to [kBrandName].
String translate(String lang, String key, {Map<String, Object?>? args, int? count}) {
  final table = kStrings[lang] ?? kStrings['en']!;
  final en = kStrings['en']!;
  String? s;
  if (count != null) {
    final cat = pluralCategory(lang, count);
    s = table['${key}_$cat'] ?? table['${key}_other'] ?? en['${key}_${count == 1 ? 'one' : 'other'}'];
  }
  s ??= table[key] ?? en[key] ?? key;
  if (!s.contains('{{')) return s;
  final all = <String, Object?>{'appName': kBrandName, ...?args};
  if (count != null) all['count'] = count;
  return s.replaceAllMapped(RegExp(r'\{\{\s*(\w+)\s*\}\}'), (m) {
    final v = all[m.group(1)];
    return v == null ? m.group(0)! : v.toString();
  });
}

/// Translation in the current language, for code without a BuildContext.
String tr(String key, {Map<String, Object?>? args, int? count}) =>
    translate(currentLanguage, key, args: args, count: count);

/// Makes the language available to widgets; dependents rebuild when it changes.
class L10n extends InheritedWidget {
  const L10n({super.key, required this.lang, required super.child});

  final String lang;

  static String of(BuildContext context) =>
      context.dependOnInheritedWidgetOfExactType<L10n>()?.lang ?? currentLanguage;

  @override
  bool updateShouldNotify(L10n oldWidget) => oldWidget.lang != lang;
}

extension L10nContext on BuildContext {
  /// Translates [key] and registers a dependency on the current language.
  String t(String key, {Map<String, Object?>? args, int? count}) =>
      translate(L10n.of(this), key, args: args, count: count);

  String get lang => L10n.of(this);
}

/// True when [key] exists (in the current language or in English).
bool hasTranslation(String key) => (kStrings[currentLanguage] ?? const {}).containsKey(key) || kStrings['en']!.containsKey(key);
